We probably want to search for the cutoff and then do a single extend rather than appending one byte at a time:

```rust
fn read_while<R, F>(r: &mut R, mut predicate: F, out: &mut Vec<u8>) -> io::Result<usize>
where
    R: BufRead,
    F: FnMut(u8) -> bool,
{
    let mut len = 0;
    loop {
        let available = r.fill_buf()?;

        if available.is_empty() {
            return Ok(len);
        }

        let i = available.iter().position(|b| !predicate(*b));

        let cutoff = i.unwrap_or(available.len());
        len += cutoff;
        out.extend_from_slice(&available[..cutoff]);
        r.consume(cutoff);

        if i.is_some() {
            return Ok(len);
        }
    }
}
```

