```rust
let wrapped_fn_name = if test_id.is_empty() {
    "_inner"
} else {
    "_inner_" + test_id
};
let (main_pre, main_post) = if returns_result {
    format!("fn main() { fn {}() -> Result<(), impl core::fmt::Debug> {", wrapped_fn_name),
    format!("}\n{}().unwrap() }", wrapped_fn_name),
} else {
    format!("fn main() { fn {}() {", wrapped_fn_name),
    format!("}\n{}() }", wrapped_fn_name),
};
