<details><summary>Example</summary>

```rust
#[test]
fn test_retain_pred_panic() {
    use std::cell::Cell;

    let dropped: [Cell<bool>; 5] = Default::default();

    struct Wrap<'a>(&'a Cell<bool>, usize);

    impl Drop for Wrap<'_> {
        fn drop(&mut self) {
            self.0.set(true);
        }
    }

    let ret = std::panic::catch_unwind(AssertUnwindSafe(|| {
        let mut v = vec![
            Wrap(&dropped[0], 0),
            Wrap(&dropped[1], 1),
            Wrap(&dropped[2], 2),
            Wrap(&dropped[3], 3),
            Wrap(&dropped[4], 4),
        ];
        v.retain(|w| match w.1 {
            0 => true,
            1 => false,
            2 => true,
            _ => panic!(),
        });
    }));
    assert!(ret.is_err());
    // Everything is dropped when predicate panicked.
    assert!(dropped.iter().all(|d| d.get()));
}
```
</details>

Another option is to use `Rc` or `Arc`, put clones in the vec, and check at the end of the count on the original ones have dropped back to 1. Then you don't need a custom type or Drop implementation.

<details><summary>Example</summary>

```rust
#[test]
fn test_retain_pred_panic() {
    use std::sync::Arc;

    let v = vec![Arc::new(0), Arc::new(1), Arc::new(2), Arc::new(3), Arc::new(4)];

    let ret = std::panic::catch_unwind(|| {
        let mut v = v.clone();
        v.retain(|w| match **w {
            0 => true,
            1 => false,
            2 => true,
            _ => panic!(),
        });
    });
    assert!(ret.is_err());
    // Everything is dropped when predicate panicked.
    assert!(v.iter().all(|r| Arc::strong_count(r) == 1));
}
```
</details>

