impl<'a, 'i, T: 'a> ManyIndices<'a, T> for &'i mut [usize] {
    type Output = ManyIndicesIter<'a, 'i, T>;
    fn get_many_mut(self, slice: &'a mut [T]) -> Result<Self::Output, GetManyMutError> {
