  671|       |                /// Returns `true` all of the flags in `other` are contained within `self`.
  672|       |                #[inline]
  673|     94|                pub const fn contains(&self, other: $BitFlags) -> bool {
  674|     94|                    (self.bits & other.bits) == other.bits
