        let inner_sp = match ori_link.find("()") {
            Some(index) => sp.with_hi(sp.lo() + BytePos(index as _)),
            None => sp,
        };
        let inner_sp = match ori_link.find("!") {
            Some(index) => sp.with_hi(sp.lo() + BytePos(index as _)),
            None => inner_sp,
        };
        let inner_sp = match ori_link.find('@') {
            Some(index) => inner_sp.with_lo(inner_sp.lo() + BytePos(index as u32 + 1)),
            None => sp,
        };
        match self {
            Self::Prefix(prefix) => {
                // FIXME: if this is an implied shortcut link, it's bad style to suggest `@`
                let mut sugg = vec![(format!("{}@", prefix), sp.with_hi(inner_sp.lo()))];
                if sp.hi() != inner_sp.hi() {
                    sugg.push(("".to_string(), inner_sp.shrink_to_hi().with_hi(sp.hi()));
                }
                sugg
            }
            Self::Function => {
                let mut sugg = vec![("()".to_string(), inner_sp.shrink_to_hi().with_hi(sp.hi()))];
                if sp.lo() != inner_sp.lo() {
                    sugg.push(("".to_string(), inner_sp.shrink_to_lo().with_lo(sp.lo()));
                }
                sugg
            }
            Self::Macro => {
                let mut sugg = vec![("!".to_string(), inner_sp.shrink_to_hi().with_hi(sp.hi()))];
                if sp.lo() != inner_sp.lo() {
                    sugg.push(("".to_string(), inner_sp.shrink_to_lo().with_lo(sp.lo()));
