extern crate test;

use test::bench::{Bencher, black_box};
use rand::{Rng, thread_rng};
use lazy_static::lazy_static;
use std::mem::transmute;

pub fn saturating_add_signed(a: u64, b: i64) -> u64 {
    if b >= 0 {
        a.saturating_add(b as _)
    } else {
        a.saturating_sub(b.unsigned_abs())
    }
}

pub fn saturating_add_signed_2(a: u64, b: i64) -> u64 {
    let (res, overflowed) = a.overflowing_add(b as _);
    if overflowed == (b < 0) {
        res
    } else if overflowed /* && b >= 0 */ {
        u64::MAX
    } else {
        0
    }
}

